import React from 'react';

export function Select({ label, options, error }: { label: string; options: string[]; error?: string }) {
  return (
    <label style={{ display: 'flex', flexDirection: 'column', gap: '6px', fontSize: '{{token:typography.scale.sm}}' }}>
      <span style={{ color: '{{token:colors.text.secondary}}' }}>{label}</span>
      <select aria-label={label} aria-invalid={!!error}
        style={{ border: `1px solid ${error ? '{{token:colors.accent.danger}}' : '{{token:colors.base.border}}'}`, borderRadius: '{{token:spacing.card.borderRadius}}', padding: '{{token:spacing.sidebar.padding}}', color: '{{token:colors.text.primary}}', background: '{{token:colors.base.surface}}' }}>
        {options.map((o) => <option key={o} value={o}>{o}</option>)}
      </select>
      {error ? <span role="alert" style={{ color: '{{token:colors.accent.danger}}', fontSize: '{{token:typography.scale.xs}}' }}>{error}</span> : null}
    </label>
  );
}
